"""Overflow-aware predictor for the b8af1dbc stack (traces generated by c_xf3s, teacher-forced through xf3s_base =
base embeddings/norm + xf3s layer edits, so the sampler parametrisation g, s, c is relative to the ORIGINAL rows).
Regimes of the generating run: normal (closed, not truncated), overflow (closed & truncated: premature close, scored ~0),
never (no close). Under candidate theta (absolute g, c; h7 scale 0.5):
 normal: P(close at t<A) -> overflow (0); P(close at t>=A) -> own correctness; S_end -> finished-state re-close
         (p_fin(theta) per G_fin tokens over the remaining budget) with own correctness, else never (0).
 overflow: the actual premature close at n-1 happens again w.p. pi_last -> 0; otherwise the trace continues thinking:
         it becomes normal w.p. q_cont with accuracy a_cont, else never.
 never: closes inside the window: t>=A -> a_L, t<A -> overflow (0); else never.
usage: predict_xf3s.py TFDIR [q_cont a_cont a_L G_fin]"""
import sys, json, numpy as np; sys.path.insert(0, '/home/user/delta/agents/f1')
from sampler import *
import hazard
tfdir = sys.argv[1]; q_cont, a_cont, a_L, G_fin = [float(x) for x in (sys.argv[2:6] or [0.5, 0.45, 0.5, 100])]
res_name = 'c_xf3s'
tr = load_dir(tfdir)
texts = {json.loads(l)['id']: json.loads(l)['text'] for l in open(f'/home/user/delta/agents/f1/results/{res_name}.texts.jsonl')}
rows = {r['id']: r for r in json.load(open(f'/home/user/delta/agents/f1/results/{res_name}.json'))['rows']}
hazard.texts_score = {i: r['score'] for i, r in rows.items()}
reg = lambda r: 'overflow' if (r['closed'] and r['truncated']) else ('normal' if r['closed'] else 'never')
pop = {}; samp = {}
for r in rows.values(): pop[reg(r)] = pop.get(reg(r), 0) + 1
for k in tr: g_ = reg(rows[int(k.split('_')[0])]); samp[g_] = samp.get(g_, 0) + 1
W = {k: pop[reg(rows[int(k.split('_')[0])])] / samp[reg(rows[int(k.split('_')[0])])] / len(rows) for k in tr}
print(f'{len(tr)} traces: sample per regime {samp}; population {pop}; weight sum {sum(W.values()):.3f}')
def predict(th):
    res = hazard.analyze(tr, texts, th)
    byid = {r['id']: r for r in res}
    norm = [r for r in res if reg(rows[r['id']]) == 'normal']
    p_fin = sum(W[f"{r['id']}_0"] * r['pi_last'] for r in norm) / max(1e-9, sum(W[f"{r['id']}_0"] for r in norm))
    strict = over = never = skip = 0.0; Wn = sum(W.values())
    for r in res:
        w = W[f"{r['id']}_0"] / Wn; rg = reg(rows[r['id']]); rem = max(0.0, 8192 - r['n'])
        pi0 = tr[f"{r['id']}_0"].probs(th)['p_close'][0]; skip += w * pi0
        if rg == 'normal':
            P_later = 1 - (1 - p_fin) ** (rem / G_fin)
            strict += w * (r['p_legit'] + r['S_end'] * P_later) * r['correct']; over += w * r['p_prem']; never += w * r['S_end'] * (1 - P_later)
        elif rg == 'overflow':
            # premature mass = closes at any observed position (all before the answer is established) incl. the actual one
            p_prem_total = r['p_prem'] + r['p_legit']   # the trace's thinking never established the answer (scored 0)
            over += w * p_prem_total; strict += w * r['S_end'] * q_cont * a_cont; never += w * r['S_end'] * (1 - q_cont)
        else:
            strict += w * r['p_legit'] * a_L; over += w * r['p_prem']; never += w * r['S_end']
    return 100 * strict, over, never, skip, p_fin
STACK = dict(g=1.4, s={k: 0.5 for k in H7}, mode='scale', c=1.3)
cands = [('xf3s stack (self)', STACK)]
for cr in [0.90, 0.92, 0.94, 0.95, 0.96, 0.97, 0.98, 1.02, 1.04]: cands.append((f'close rel {cr} (c={1.3*cr:.3f})', dict(STACK, c=1.3 * cr)))
for gr in [0.9, 0.95, 1.05, 1.1]: cands.append((f'gain rel {gr} (g={1.4*gr:.2f})', dict(STACK, g=1.4 * gr)))
cands.append(('close rel 0.96 + gain rel 1.05', dict(STACK, c=1.3 * 0.96, g=1.4 * 1.05)))
cands.append(('h13 dampen', dict(STACK, s={k: 0.5 for k in H13})))
cands.append(('h13 + close rel 0.96', dict(STACK, s={k: 0.5 for k in H13}, c=1.3 * 0.96)))
print('candidate | predicted strict | overflow share | never share | skip share | p_fin')
for name, th in cands:
    s, o, nv, sk, pf = predict(th); print(f'{name:34s} strict {s:5.1f}  overflow {o:.3f}  never {nv:.3f}  skip {sk:.3f}  p_fin {pf:.2f}')
